	public function single_file_upload($my_file, $file_path, $types = "*", $thumb = 1)
	{
		$this->load->library('upload');

		$config = array(
			'allowed_types' => $types,  //'gif|jpg|jpeg|png|iso|dmg|zip|rar|doc|docx|xls|xlsx|ppt|pptx|csv|ods|odt|odp|pdf|rtf|sxc|sxi|txt|exe|avi|mpeg|mp3|mp4|3gp',
			'upload_path' => '../public_html/assets/' . $file_path,
			// 'upload_path' => '../assets/'.$file_path,
			'overwrite' => FALSE,
			'max_size' => 20000
		);

		$this->load->library('upload');
		$this->upload->initialize($config);

		if ($this->upload->do_upload($my_file)) {
			$image_data = $this->upload->data();
		} else {
			$error = $this->upload->display_errors();
			return false;
		}

		if ($thumb == 1) {
			$config = array(
				'source_image' => $image_data['full_path'],
				'new_image' => COMPANY_SITE . '/assets/' . $file_path . '/thumbs',
				'maintain_ration' => TRUE,
				'width' => 250
			);

			$this->load->library('image_lib', $config);
			$this->image_lib->resize();
		}

		return $image_data['file_name'];
	}

	public function filedownload($file_path, $file_name = NULL)
	{
		if ($file_name) {
			//load download helper
			$this->load->helper('download');

			$file = COMPANY_SITE . '/assets/' . $file_path . '/' . $file_name;

			$ch = curl_init($file);

			curl_setopt($ch, CURLOPT_NOBODY, true);
			curl_exec($ch);
			$retcode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
			// $retcode >= 400 -> not found, $retcode = 200, found.

			if ($retcode == 200) {
				// read file contents
				$data = file_get_contents($file);
				force_download($file_name, $data);
				return true;
			} else {
				return "No file found.";
			}
			curl_close($ch);
		} else {
			return "No file found.";
		}
	}

